// Generated by scripts/cache-bust.sh.
// Forward the loader's ?v= build stamp to worker.js and worker_bg.wasm so those
// unhashed URLs are invalidated on deploy too. The ?data= stamp on this loader's URL is
// read by the worker itself to version its database fetch.
(function () {
  var v = new URL(self.location.href).searchParams.get("v");
  var q = v ? "?v=" + encodeURIComponent(v) : "";
  importScripts("./worker.js" + q);
  wasm_bindgen("./worker_bg.wasm" + q);
})();
